// Worker entry point. Wraps the OpenNext-generated worker (built into .open-next/)
// and adds a scheduled handler for the batched phone notifications.

// @ts-ignore generated by `opennextjs-cloudflare build`
import openNext, { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from './.open-next/worker.js';
import { sendDigest } from './lib/notifyDigest';

export { DOQueueHandler, DOShardedTagCache, BucketCachePurge };

export default {
  fetch: (request: Request, env: unknown, ctx: unknown) => openNext.fetch(request, env, ctx),

  async scheduled(_event: unknown, env: any, ctx: { waitUntil(p: Promise<unknown>): void }) {
    ctx.waitUntil(sendDigest(env).catch((e: unknown) => console.error('Notification digest failed:', e)));
  },
};
